SELECT  /* LGVATT40010.retrievePlanApproverSameCheck */
        NVL((
             SELECT 'Y' AS approver_same_flag
             FROM   lgcom_approval_status_n as_p
                  , lgcom_approval_status_n as_r
             WHERE  as_p.request_master_id = #{requestMasterIdPlan}
             AND    as_p.request_code      = #{requestCodePlan}
             AND    as_r.request_master_id = #{requestMasterResult}
             AND    as_r.request_code      = #{requestCodeResult}
             AND    as_r.approval_seqs     = as_p.approval_seqs
             AND    as_r.process_seq_no    = as_p.process_seq_no
             AND    as_r.user_no           = as_p.user_no
             HAVING COUNT(as_p.request_master_id) = (SELECT COUNT(as_r0.request_master_id) /* 실적결재자 건수 와 실적결재자와 동일한 계획결재자 건수가 동일한지 체크 */
                                                     FROM   lgcom_approval_status_n as_r0
                                                     WHERE  as_r0.request_master_id = #{requestMasterResult}
                                                     AND    as_r0.request_code      = #{requestCodeResult}
                                                     )
            ), 'N') AS approver_same_flag /* 실적결재자와 계획결재자가 동일한지 여부 */
      ,(SELECT DECODE(as_p0.status_code, '20', 'Y', 'N') /* 계획근태가 결재요청(20)인 경우만 삭제하기 위한 값 */
        FROM   lgcom_approval_request_n as_p0
        WHERE  as_p0.request_master_id = #{requestMasterIdPlan}
        AND    as_p0.request_code      = #{requestCodePlan}
       ) AS approval_wait_flag /* 계획결재 대기상태여부 */
FROM    DUAL
